"""Embedded AVL logo — forked from render_deck.py.

The sandbox pipeline must not import anything the production endpoint uses, so
the white-logo PNG blob is copied here rather than reached for via
``import render_deck``. Only the white variant is needed: the RFQ Insight
renderer never draws the green recolour.

Source: render_deck.py (AVL_WHITE_B64 / _logo_white_stream).
"""

import base64
import io

AVL_WHITE_B64 = ""

_WHITE_BYTES = base64.b64decode(AVL_WHITE_B64)


def logo_white_stream():
    """A fresh BytesIO over the logo PNG — python-pptx consumes the stream, so
    every picture placement needs its own."""
    return io.BytesIO(_WHITE_BYTES)
